1. import * as vscode from "vscode";
2. import * as assert from "assert";
3. import { activate, getDocUri, sleep } from "./helper";
4. 
5. suite("VS Code Integration Tests", async () => {
6.   const docUri = getDocUri("diagnostics.txt");
7. 
8.   suiteSetup(async () => {
9.     await activate(docUri);
10.   });
11. 
12.   test("Diagnoses typo", async () => {
13.     await testDiagnostics(docUri, [
14.       {
15.         message: "`apropriate` should be `appropriate`",
16.         range: toRange(0, 11, 0, 21),
17.         severity: vscode.DiagnosticSeverity.Warning,
18.         source: "ex",
19.       },
20.       {
21.         message: "`fo` should be `of`, `for`, `do`, `go`, `to`",
22.         range: toRange(1, 0, 1, 2),
23.         severity: vscode.DiagnosticSeverity.Warning,
24.         source: "ex",
25.       },
26.     ]);
27.   });
28. 
29.   test("Auto fix applies corrections", async () => {
30.     let editor = vscode.window.activeTextEditor;
31. 
32.     if (!editor) {
33.       throw new Error("no active editor");
34.     }
35. 
36.     // place cursor on the spelling mistake
37.     let position = new vscode.Position(0, 13);
38.     let selection = new vscode.Selection(position, position);
39.     editor.selection = selection;
40. 
41.     // for GHA CI to work, we need to wait long enough for the
42.     // cursor to move to the spelling mistake, otherwise the
43.     // autofix won't trigger
44.     await sleep(1000);
45. 
46.     // trigger correction
47.     await vscode.commands.executeCommand("editor.action.autoFix");
48.     await sleep(100);
49. 
50.     let contents = vscode.window.activeTextEditor?.document.getText();
51.     assert.equal(contents, "this is an appropriate test\nfo typos\n");
52.   });
53. });
54. 
55. function toRange(sLine: number, sChar: number, eLine: number, eChar: number) {
56.   const start = new vscode.Position(sLine, sChar);
57.   const end = new vscode.Position(eLine, eChar);
58.   return new vscode.Range(start, end);
59. }
